function InlineFeedbackForm({
  taskId,
  taskName,
  taskDescription,
  onSubmit,
  onCancel,
  submitting,
}: {
  taskId: string;
  taskName: string;
  taskDescription?: string;
  onSubmit: (feedback: { taskId: string; taskName: string; type: 'down'; notes: string; images: File[]; timestamp: number; mode: 'text'; taskDescription?: string }) => void;
  onCancel: () => void;
  submitting: boolean;
}) {
  const [notes, setNotes] = useState('');
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    // Auto-focus the textarea when it appears
    setTimeout(() => inputRef.current?.focus(), 50);
  }, []);

  const handleSubmit = () => {
    if (!notes.trim()) return;
    onSubmit({
      taskId,
      taskName,
      type: 'down',
      notes,
      images: [],
      timestamp: Date.now(),
      mode: 'text',
      taskDescription,
    });
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
