    if (e.key === 'Escape') {
      onCancel();
    }
  };

  return (
    <div
      className="mt-1 bg-[#0d0815]/80 backdrop-blur-md border border-red-400/20 rounded-xl p-3 space-y-2 animate-in slide-in-from-top-2 duration-200"
